-------------------
---- AUTOSTART ----
-------------------

hl.on("hyprland.start", function()
    -- Execute your favorite apps at launch
    -- hl.exec_cmd("garuda-welcome")

    -- Add networkmanager applet to tray in waybar
    hl.exec_cmd("nm-applet --indicator")

    -- Set keyboard layout
    -- hl.exec_cmd(".local/bin/garuda-locale.sh")

    -- Set monitor values. For own values, please comment with #
    -- hl.exec_cmd(".local/bin/mon.sh")

    -- background
    hl.exec_cmd("wpaperd")

    -- status bar
    hl.exec_cmd("waybar")

    hl.exec_cmd("mako")
    hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")

    -- experimental(might work might won't)
    hl.exec_cmd("xrdb -load ~/.Xresources")

    -- Clipboard Manager
    hl.exec_cmd("wl-paste --type text --watch cliphist store")  -- Stores only text data
    hl.exec_cmd("wl-paste --type image --watch cliphist store") -- Stores only image data

    -- Use gtk-settings
    hl.exec_cmd("apply-gsettings")

    -- low battery warning script
    hl.exec_cmd(".local/bin/battery_warn.sh")

    -- Select Kitty font size once from monitor resolution.
    hl.exec_cmd(".local/bin/kitty-font-autosize.sh")

    -- Hypr Ecosystem
    -- hypridle
    hl.exec_cmd("hypridle")
end)

