-- some env variables
hl.env("XDG_CURRENT_DESKTOP", "Hyprland")
-- we usually prefer things to be set up through script
-- have a look at hyprstart file


-- For all categories, see https://wiki.hyprland.org/Configuring/Variables/
-- For kb_model check /usr/share/X11/xkb/rules/base.lst
hl.config({
    input = {
        kb_layout  = "us",
        kb_variant = "altgr-intl",
        kb_model   = "pc105",
        kb_options = "",
        kb_rules   = "",

        numlock_by_default = true,
        follow_mouse       = 1,

        touchpad = {
            natural_scroll       = true,
            tap_to_click         = true,
            disable_while_typing = true,
        },

        sensitivity = 0, -- -1.0 - 1.0, 0 means no modification.
    },
})

hl.config({
    general = {
        -- See https://wiki.hyprland.org/Configuring/Variables/ for more

        gaps_in     = 5,
        gaps_out    = 10,
        border_size = 2,

        col = {
            active_border   = { colors = { "rgba(33ccffee)", "rgba(8f00ffee)" }, angle = 45 },
            inactive_border = "rgba(595959aa)",
        },

        layout = "dwindle",
    },
})

hl.config({
    decoration = {
        -- See https://wiki.hyprland.org/Configuring/Variables/ for more

        rounding = 10,

        blur = {
            enabled = true,
            size    = 5,
            passes  = 3,
        },

        shadow = {
            enabled      = true,
            range        = 4,
            render_power = 3,
            color        = "rgba(1a1a1aee)",
        },
    },
})

-- Apply blur universally to all layer-shell surfaces
hl.layer_rule({
    name = "blur-all-layers",

    match = {
        namespace = ".*",
    },

    blur         = true,
    blur_popups  = true,
    ignore_alpha = 0.10,
})

hl.config({
    animations = {
        enabled = true,
    },
})

-- Some default animations, see https://wiki.hyprland.org/Configuring/Animations/ for more
hl.curve("myBezier", { type = "bezier", points = { { 0.05, 0.9 }, { 0.1, 1.05 } } })

hl.animation({ leaf = "windows",    enabled = true, speed = 7,  bezier = "myBezier" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 7,  bezier = "default",  style = "popin 80%" })
hl.animation({ leaf = "border",     enabled = true, speed = 10, bezier = "default" })
hl.animation({ leaf = "fade",       enabled = true, speed = 7,  bezier = "default" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 6,  bezier = "default" })

hl.config({
    dwindle = {
        -- See https://wiki.hyprland.org/Configuring/Dwindle-Layout/ for more
        -- pseudotile was removed in newer Hyprland versions.
        -- Pseudotiling is still toggled with mainMod + P below.
        preserve_split = true, -- you probably want this
    },
})

hl.config({
    master = {
        -- See https://wiki.hyprland.org/Configuring/Master-Layout/ for more
        new_status = "master",
    },
})

hl.gesture({
    fingers   = 3,
    direction = "up",
    action    = function()
        hl.exec_cmd("garuda-toolbox")
    end,
})

hl.gesture({
    fingers   = 3,
    direction = "down",
    action    = function()
        hl.exec_cmd("nwg-drawer -mb 10 -mr 10 -ml 10 -mt 10")
    end,
})

hl.gesture({
    fingers   = 3,
    direction = "horizontal",
    action    = "workspace",
})

hl.config({
    misc = {
        disable_hyprland_logo = true,
    },
})

