-- See https://wiki.hyprland.org/Configuring/Keywords/ for more
local mainMod = "SUPER"

local function bind_exec(keys, cmd, opts)
    hl.bind(keys, hl.dsp.exec_cmd(cmd), opts)
end

-- Example binds, see https://wiki.hyprland.org/Configuring/Binds/ for more
bind_exec(mainMod .. " + SHIFT + R", "hyprctl reload")
bind_exec(mainMod .. " + code:36", "kitty") -- 36 = Enter
bind_exec(mainMod .. " + T", "kitty")
hl.bind(mainMod .. " + Q", hl.dsp.window.close())
bind_exec(mainMod .. " + SHIFT + E", "nwgbar")
bind_exec(mainMod .. " + N", "thunar")
hl.bind(mainMod .. " + SHIFT + code:65", hl.dsp.window.float({ action = "toggle" }))
bind_exec("SUPER + D", "pkill wofi || wofi --normal-window --show drun --allow-images", { release = true })
bind_exec(mainMod .. " + E", "emote")
bind_exec(mainMod .. " + SHIFT + D", "nwg-drawer -mb 10 -mr 10 -ml 10 -mt 10")
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())       -- dwindle
hl.bind(mainMod .. " + SHIFT + P", hl.dsp.layout("togglesplit")) -- dwindle
bind_exec(mainMod .. " + V", "cliphist list | wofi --dmenu | cliphist decode | wl-copy")
bind_exec(mainMod .. " + B", "brightnessctl -c backlight set 1%-")
bind_exec(mainMod .. " + SHIFT + B", "brightnessctl -c backlight set +1%")

-- Mainmod + Function keys
bind_exec(mainMod .. " + F1",  "firedragon")
bind_exec(mainMod .. " + F2",  "thunderbird")
bind_exec(mainMod .. " + F3",  "thunar")
bind_exec(mainMod .. " + F4",  "geany")
bind_exec(mainMod .. " + F5",  "github-desktop")
bind_exec(mainMod .. " + F6",  "gparted")
bind_exec(mainMod .. " + F7",  "inkscape")
bind_exec(mainMod .. " + F8",  "blender")
bind_exec(mainMod .. " + F9",  "meld")
bind_exec(mainMod .. " + F10", "joplin-desktop")
bind_exec(mainMod .. " + F11", "snapper-tools")
bind_exec(mainMod .. " + F12", "galculator")

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "l" }))
hl.bind(mainMod .. " + H",     hl.dsp.focus({ direction = "l" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "r" }))
hl.bind(mainMod .. " + L",     hl.dsp.focus({ direction = "r" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "u" }))
hl.bind(mainMod .. " + K",     hl.dsp.focus({ direction = "u" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "d" }))
hl.bind(mainMod .. " + J",     hl.dsp.focus({ direction = "d" }))

-- Switch workspaces with mainMod + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key, hl.dsp.focus({ workspace = i }))
end

-- Move to workspace with focused container with ALT + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind("ALT + SHIFT + " .. key, hl.dsp.window.move({ workspace = i, follow = true }))
end

-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i, follow = false }))
end

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- status bar
-- Converted from old line:
-- layerrule = match:class waybar, match:float yes
-- NOTE: layer rules match namespace, not class/float. Kept the useful waybar rule below.
hl.layer_rule({
    match        = { namespace = "waybar" },
    ignore_alpha = 0.5,
})

-- set volume (laptops only and may or may not work on PCs)
bind_exec('code:122', 'pamixer --decrease 5; notify-send " Volume: "$(pamixer --get-volume) -t 500')
bind_exec('code:123', 'pamixer --increase 5; notify-send " Volume: "$(pamixer --get-volume) -t 500')
bind_exec('code:121', 'pamixer --toggle-mute; notify-send " Volume: Toggle-mute" -t 500')
bind_exec('XF86AudioMicMute', 'pactl set-source-mute @DEFAULT_SOURCE@ toggle; notify-send "System Mic: Toggle-mute" -t 500')

-- other bindings
bind_exec(mainMod .. " + O", "firedragon")
hl.bind(mainMod .. " + M", hl.dsp.window.fullscreen({ mode = "maximized" }))
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen({ mode = "fullscreen" }))
hl.bind(mainMod .. " + SHIFT + F", hl.dsp.window.fullscreen_state({ internal = 0, client = 2 }))
bind_exec("code:232", "brightnessctl -c backlight set 5%-")
bind_exec("code:233", "brightnessctl -c backlight set +5%")
bind_exec(mainMod .. " + SHIFT + C", "killall -9 wpaperd && wpaperd")

-- https://github.com/hyprwm/contrib/blob/main/grimblast/grimblast.1.scd
-- Print: All outputs
-- SHIFT+Print: Select area
-- $mainMod+Print: Current window
-- $mainMod+Shift+Print: Current output

hl.bind("Print", hl.dsp.exec_cmd("grimblast save screen && notify-send Screenshot captured"))
hl.bind("SHIFT + Print", hl.dsp.exec_cmd("grimblast save area && notify-send Selected\\ area captured"))
hl.bind(mainMod .. " + Print", hl.dsp.exec_cmd("grimblast save active && notify-send Active\\ window captured"))
hl.bind(mainMod .. " + SHIFT + Print", hl.dsp.exec_cmd("grimblast output active && notify-send Output captured"))

-- for resizing window
-- will switch to a submap called resize
hl.bind(mainMod .. " + R", hl.dsp.submap("resize"))

-- will start a submap called "resize"
hl.define_submap("resize", function()
    -- sets repeatable binds for resizing the active window
    hl.bind("right", hl.dsp.window.resize({ x = 50,  y = 0,   relative = true }), { repeating = true })
    hl.bind("L",     hl.dsp.window.resize({ x = 50,  y = 0,   relative = true }), { repeating = true })
    hl.bind("left",  hl.dsp.window.resize({ x = -50, y = 0,   relative = true }), { repeating = true })
    hl.bind("H",     hl.dsp.window.resize({ x = -50, y = 0,   relative = true }), { repeating = true })
    hl.bind("up",    hl.dsp.window.resize({ x = 0,   y = -50, relative = true }), { repeating = true })
    hl.bind("K",     hl.dsp.window.resize({ x = 0,   y = -50, relative = true }), { repeating = true })
    hl.bind("down",  hl.dsp.window.resize({ x = 0,   y = 50,  relative = true }), { repeating = true })
    hl.bind("J",     hl.dsp.window.resize({ x = 0,   y = 50,  relative = true }), { repeating = true })

    -- use reset to go back to the global submap
    hl.bind("escape", hl.dsp.submap("reset"))
end)

-- will reset the submap, meaning end the current one and return to the global one
-- submap=reset

-- to move window
hl.bind(mainMod .. " + SHIFT + up",    hl.dsp.window.move({ direction = "u" }))
hl.bind(mainMod .. " + SHIFT + K",     hl.dsp.window.move({ direction = "u" }))
hl.bind(mainMod .. " + SHIFT + down",  hl.dsp.window.move({ direction = "d" }))
hl.bind(mainMod .. " + SHIFT + J",     hl.dsp.window.move({ direction = "d" }))
hl.bind(mainMod .. " + SHIFT + left",  hl.dsp.window.move({ direction = "l" }))
hl.bind(mainMod .. " + SHIFT + H",     hl.dsp.window.move({ direction = "l" }))
hl.bind(mainMod .. " + SHIFT + right", hl.dsp.window.move({ direction = "r" }))
hl.bind(mainMod .. " + SHIFT + L",     hl.dsp.window.move({ direction = "r" }))

-- special workspace

hl.bind(mainMod .. " + SHIFT + S", hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "+0", follow = true }))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic", follow = true }))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.workspace.toggle_special("magic"))

-- other blurings
-- blurls = wofi
-- blurls = thunar
-- blurls = gedit
-- blurls = gtk-layer-shell # for nwg-drawer
-- blurls = catfish
hl.layer_rule({ match = { namespace = "wofi" },            blur = true })
hl.layer_rule({ match = { namespace = "thunar" },          blur = true })
hl.layer_rule({ match = { namespace = "gedit" },           blur = true })
hl.layer_rule({ match = { namespace = "gtk-layer-shell" }, blur = true }) -- for nwg-drawer
hl.layer_rule({ match = { namespace = "catfish" },         blur = true })

-- window rules
-- nwgbar :
hl.layer_rule({
    match      = { namespace = ".*nwgbar.*" },
    blur       = true,
    dim_around = false,
})

hl.window_rule({ match = { title = "thunar" },  opacity = "0.85 override 0.85 override" })
hl.window_rule({ match = { title = "gedit" },   opacity = "0.85 override 0.85 override" })
hl.window_rule({ match = { title = "catfish" }, opacity = "0.85 override 0.85 override" })
hl.window_rule({ match = { title = "wofi" },    stay_focused = true })

-- window rules with evaluation
hl.window_rule({
    name    = "windowrule-1",
    opacity = "0.85 0.85",
    match   = { float = true },
})

-- video play paues bindings
bind_exec("code:172", "playerctl play-pause")
bind_exec("code:171", "playerctl next")
bind_exec("code:173", "playerctl previous")

-- Performance Tweaks (For less power consumption without sacrificing performance)
-- See : https://wiki.hyprland.org/Configuring/Performance/
-- Hyprland 0.55+ uses debug.vfr. It defaults to true; keep it explicit here.
hl.config({
    debug = {
        vfr = true,
    },
})

-- enable G-Hyprland
bind_exec(mainMod .. " + SHIFT + G", "kitty -e ~/.local/bin/bear/implement_gum.sh enable")

